const APP_TITLE='RASME Self-Study',TZ='Asia/Bangkok',WEB_APP_URL_FALLBACK='https://script.google.com/macros/s/AKfycbxsR84XffxsZpIGA1ZMuoZNdK-sMaXx92l5mRXY1FiPcOLYdLcf32bVIsHHflleFDjG/exec';
let ACTIVE_SS_=null;
const SS=()=>ACTIVE_SS_||(ACTIVE_SS_=SpreadsheetApp.getActiveSpreadsheet());
const SCHEMAS={
 Users:['UserID','StudentID','FullName','Affiliation','ProgramType','AcademicYear','Email','Phone','PasswordHash','Salt','Role','Status','NoShowCount','BanUntil','EvaluationPending','CreatedAt','UpdatedAt'],
 Procedures:['ProcedureID','ProcedureName','Description','Location','Floor','Room','ImageURL','Rules','Status','SortOrder'],
 Sessions:['SessionID','ProcedureID','SessionDate','StartTime','EndTime','Room','Floor','MinCapacity','MaxCapacity','BookingOpenDate','BookingCloseDays','Status','Notes'],
 Bookings:['BookingID','UserID','SessionID','Status','BookedAt','CancelledAt','CheckInAt','CheckOutAt','EvaluationCompletedAt','UpdatedBy','Notes'],ActiveBookings:['BookingID','UserID','SessionID','Status','BookedAt','CancelledAt','CheckInAt','CheckOutAt','EvaluationCompletedAt','UpdatedBy','Notes'],
 Evaluations:['EvaluationID','BookingID','UserID','Rating','Feedback','SubmittedAt','SatisfactionBooking','SatisfactionEquipment','SatisfactionEnvironment','SatisfactionOverall','ConfidenceBefore','ConfidenceAfter','ConfidenceChange','ProcedureID','ProcedureName','SessionID','FormVersion','ConfidenceMethod','SatisfactionStaff','ConfidenceCoreBefore','ConfidenceCoreAfter','ConfidenceCoreChange','ConfidenceSafetyBefore','ConfidenceSafetyAfter','ConfidenceSafetyChange','ConfidenceComplicationsBefore','ConfidenceComplicationsAfter','ConfidenceComplicationsChange','SatisfactionReturn','SatisfactionRecommend','ConfidenceSelfPractice','MostImpressed','ImprovementNeeded','OtherSuggestion','ConfidenceSelfPracticeBefore','ConfidenceSelfPracticeAfter','ConfidenceSelfPracticeChange'],
 AuthSessions:['TokenHash','UserID','ExpiresAt','CreatedAt'],PasswordResets:['TokenHash','UserID','ExpiresAt','UsedAt','CreatedAt'],NotificationQueue:['QueueID','Channel','Recipient','Subject','Message','Event','ReferenceID','Status','Attempts','NextAttemptAt','CreatedAt','SentAt','Error'],Settings:['Key','Value','Description']};
const DEFAULTS=[['BOOKING_CLOSE_DAYS','7','ปิดรับก่อนวันนัด'],['CANCELLATION_DAYS','3','ยกเลิกก่อนวันนัด'],['MIN_PARTICIPANTS','2','ขั้นต่ำต่อรอบ'],['DEFAULT_CAPACITY','4','ความจุเริ่มต้น'],['NO_SHOW_GRACE_MINUTES','15','เวลาผ่อนผัน'],['NO_SHOW_PROCESSING_BUFFER_MINUTES','5','ช่วงกันชนก่อนงานอัตโนมัติบันทึก No-show'],['NO_SHOW_LIMIT','3','No-show ก่อนแบน'],['SUSPENSION_DAYS','3','จำนวนวันแบน'],['SESSION_HOURS','24','อายุ login'],['LOGIN_MAX_ATTEMPTS','5','จำนวนครั้งที่ลองผิดก่อนพัก'],['LOGIN_LOCK_MINUTES','15','เวลาพักการเข้าสู่ระบบ'],['NOTIFICATION_MAX_RETRIES','3','จำนวนครั้งส่งแจ้งเตือนซ้ำ'],['DATA_RETENTION_DAYS','90','อายุข้อมูลเทคนิค'],['WEB_APP_URL','https://script.google.com/macros/s/AKfycbxsR84XffxsZpIGA1ZMuoZNdK-sMaXx92l5mRXY1FiPcOLYdLcf32bVIsHHflleFDjG/exec','URL deployment สำหรับผู้ใช้งาน'],['TELEGRAM_BOT_TOKEN','','ตั้งค่าใน Script Properties'],['TELEGRAM_CHAT_ID','','ตั้งค่าใน Script Properties'],['CENTER_RULES','เข้าเมนูการจองของฉัน กดขอ Check-in แล้วแจ้งรหัส 3 ตัวให้เจ้าหน้าที่ตรวจสอบและยืนยัน|จัดเก็บอุปกรณ์หลังใช้งาน|ห้ามนำอาหารและเครื่องดื่มเข้าพื้นที่','คั่นด้วย |']];
const CENTER_RULES_DEFAULT='เข้าเมนูการจองของฉัน กดขอ Check-in แล้วแจ้งรหัส 3 ตัวให้เจ้าหน้าที่ตรวจสอบและยืนยัน|จัดเก็บอุปกรณ์หลังใช้งาน|ห้ามนำอาหารและเครื่องดื่มเข้าพื้นที่';
const centerRulesDefaultRow_=DEFAULTS.find(r=>r[0]==='CENTER_RULES');if(centerRulesDefaultRow_)centerRulesDefaultRow_[1]=CENTER_RULES_DEFAULT;

function doGet(e){const t=HtmlService.createTemplateFromFile('index'),p=e&&e.parameter||{};t.resetToken=p.reset||'';t.appUrl=WEB_APP_URL_FALLBACK;return t.evaluate().setTitle(APP_TITLE).addMetaTag('viewport','width=device-width, initial-scale=1, maximum-scale=1, viewport-fit=cover').setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);}
function initializeSystem(){ensureProductionUpgrade_();installAutomationTriggers();return{success:true};}
/** Run once from the Apps Script editor to create or replace the single admin account. */
function setupAdminAccount_(studentId,password,fullName,email){ensureSystem_();if(!studentId||String(password||'').length<8)throw Error('ระบุ username และรหัสผ่านอย่างน้อย 8 ตัวอักษร');const sh=SS().getSheetByName('Users'),old=rows_(sh).find(u=>u.Role==='Admin'),salt=token_(),now=new Date();if(old){update_(sh,'UserID',old.UserID,{StudentID:norm_(studentId),FullName:fullName||'RASME Admin',Email:email||old.Email,PasswordHash:passV2_(password,salt),Salt:salt,Status:'Active',UpdatedAt:now});return{success:true,userId:old.UserID};}const id=id_('ADM');sh.appendRow([id,norm_(studentId),fullName||'RASME Admin','RASME','Admin','Staff',email||'', '',passV2_(password,salt),salt,'Admin','Active',0,'',false,now,now]);return{success:true,userId:id};}
function ensureSystem_(){const ss=SS();Object.keys(SCHEMAS).forEach(n=>{let s=ss.getSheetByName(n);if(!s)s=ss.insertSheet(n);if(!s.getLastRow())s.appendRow(SCHEMAS[n]);});repairUsersSchema_();repairBookingsSchema_();const s=ss.getSheetByName('Settings'),keys=new Set(rows_(s).map(r=>String(r.Key)));DEFAULTS.forEach(r=>{if(!keys.has(r[0]))s.appendRow(r);});}
function repairUsersSchema_(){const sh=SS().getSheetByName('Users'),expected=SCHEMAS.Users,current=sh.getRange(1,1,1,expected.length).getDisplayValues()[0];if(current[0]==='UserID'&&current[1]==='StudentID')return;const legacy=current[0]==='UID'||current[1]==='Full Name';if(legacy&&sh.getLastColumn()>=expected.length){sh.getRange(1,1,1,expected.length).setValues([expected]);sh.setFrozenRows(1);SpreadsheetApp.flush();}}
function repairBookingsSchema_(){const ss=SS(),sh=ss.getSheetByName('Bookings'),expected=SCHEMAS.Bookings,current=sh.getRange(1,1,1,Math.max(expected.length,14)).getDisplayValues()[0];if(current[0]==='BookingID'&&current[1]==='UserID'&&current[2]==='SessionID')return;const legacy=current[0]==='BookingID'&&current[1]==='StudentID';if(!legacy)return;const values=sh.getDataRange().getValues(),newRows=values.slice(1).filter(r=>String(r[1]||'').indexOf('USR-')===0&&String(r[2]||'').indexOf('SES-')===0).map(r=>r.slice(0,expected.length));let name='Bookings_Legacy_'+Utilities.formatDate(new Date(),TZ,'yyyyMMdd_HHmmss'),i=1;while(ss.getSheetByName(name))name='Bookings_Legacy_'+Utilities.formatDate(new Date(),TZ,'yyyyMMdd_HHmmss')+'_'+i++;sh.setName(name);const fresh=ss.insertSheet('Bookings');fresh.getRange(1,1,1,expected.length).setValues([expected]);fresh.setFrozenRows(1);if(newRows.length)fresh.getRange(2,1,newRows.length,expected.length).setValues(newRows);SpreadsheetApp.flush();}
function getPublicBootstrap(token){ensureProductionUpgrade_();const u=sessionUser_(token),data=publicData_();return{user:u?publicUser_(u):null,settings:data.settings,procedures:data.procedures,scheduleOverview:data.scheduleOverview};}

function ensureProductionUpgrade_(){const props=PropertiesService.getScriptProperties();if(props.getProperty('SCHEMA_VERSION')==='8')return;const lock=LockService.getScriptLock();if(!lock.tryLock(10000))return;try{if(props.getProperty('SCHEMA_VERSION')==='8')return;ensureSystem_();const active=SS().getSheetByName('ActiveBookings');if(active.getLastRow()<2){const current=rows_(SS().getSheetByName('Bookings')).filter(b=>['Reserved','Confirmed','CheckedIn','CheckedOut'].includes(String(b.Status)));if(current.length)active.getRange(2,1,current.length,SCHEMAS.ActiveBookings.length).setValues(current.map(b=>SCHEMAS.ActiveBookings.map(k=>b[k]===undefined?'':b[k])));}const settings=SS().getSheetByName('Settings'),rules=find_(settings,'Key','CENTER_RULES');if(rules){const current=String(rules.Value||''),parts=current.split('|').map(x=>/(สแกน QR เพื่อ Check-in|เปิด QR Check-in|แสดง QR Code ให้เจ้าหน้าที่)/.test(x)?'เข้าเมนูการจองของฉัน กดขอ Check-in แล้วแจ้งรหัส 3 ตัวให้เจ้าหน้าที่ตรวจสอบและยืนยัน':x);const next=parts.join('|');if(next!==current)update_(settings,'Key','CENTER_RULES',{Value:next});}props.setProperty('SCHEMA_VERSION','8');}finally{lock.releaseLock();}}

function registerUser(d){return withMutationLock_(()=>registerUserLocked_(d));}
function registerUserLocked_(d){['studentId','fullName','affiliation','programType','academicYear','email','phone','password'].forEach(k=>{if(!String(d[k]||'').trim())throw Error('กรุณากรอกข้อมูลให้ครบ');});if(String(d.password).length<8)throw Error('รหัสผ่านต้องมีอย่างน้อย 8 ตัวอักษร');const sh=SS().getSheetByName('Users'),sid=norm_(d.studentId),email=String(d.email).trim().toLowerCase();if(columnHas_(sh,'StudentID',x=>sameStudentId_(x,sid))||columnHas_(sh,'Email',x=>String(x).toLowerCase()===email))throw Error('รหัสนักศึกษา/บุคลากรหรืออีเมลนี้ลงทะเบียนแล้ว กรุณาเข้าสู่ระบบหรือใช้เมนูลืมรหัสผ่าน');const id=id_('USR'),salt=token_(),now=new Date(),user={UserID:id,StudentID:sid,FullName:clean_(d.fullName),Affiliation:clean_(d.affiliation),ProgramType:clean_(d.programType),AcademicYear:clean_(d.academicYear),Email:email,Phone:clean_(d.phone),PasswordHash:passV2_(d.password,salt),Salt:salt,Role:'Student',Status:'Active',NoShowCount:0,BanUntil:'',EvaluationPending:false,CreatedAt:now,UpdatedAt:now};const row=appendRow_(sh,SCHEMAS.Users.map(key=>user[key]===undefined?'':user[key]));setText_(sh,row,SCHEMAS.Users.indexOf('StudentID')+1,sid);setText_(sh,row,SCHEMAS.Users.indexOf('Phone')+1,user.Phone);return{success:true,token:makeSession_(id,user),user:publicUser_(user)};}
function login(studentId,password){const sh=SS().getSheetByName('Users'),typedId=norm_(studentId);checkLoginRate_(typedId);const candidates=rowsMatchingColumn_(sh,'StudentID',x=>sameStudentId_(x,typedId)),u=candidates.slice().reverse().find(x=>verifyPassword_(password,x.PasswordHash,x.Salt));if(!u){recordLogin_(typedId,false,'ข้อมูลไม่ถูกต้อง');throw Error('รหัสนักศึกษา/บุคลากรหรือรหัสผ่านไม่ถูกต้อง');}if(u.Status==='Disabled'){recordLogin_(typedId,false,'บัญชีถูกระงับ');throw Error('บัญชีถูกระงับ กรุณาติดต่อศูนย์');}recordLogin_(typedId,true,'');const changes={};if(norm_(u.StudentID)!==typedId){setText_(sh,u._row,SCHEMAS.Users.indexOf('StudentID')+1,typedId);u.StudentID=typedId;}if(String(u.PasswordHash).indexOf('v2$')!==0){u.PasswordHash=passV2_(password,u.Salt);changes.PasswordHash=u.PasswordHash;}if(Object.keys(changes).length)updateRow_(sh,u._row,changes);refreshBan_(u);return{success:true,token:makeSession_(u.UserID,u),user:publicUser_(u)};}
function logout(token){const tokenHash=hash_(token||''),key='auth:'+tokenHash,sh=SS().getSheetByName('AuthSessions'),row=findRowNumber_(sh,'TokenHash',tokenHash);CacheService.getScriptCache().remove(key);if(row>=2){sh.deleteRow(row);invalidateSheetCaches_(sh);}return{success:true};}
function requestPasswordReset(value){value=String(value||'').trim().toLowerCase();const sh=SS().getSheetByName('Users'),byId=rowsMatchingColumn_(sh,'StudentID',x=>sameStudentId_(x,value)),u=byId[0]||rowsMatchingColumn_(sh,'Email',x=>String(x).toLowerCase()===value)[0];if(u){const t=token_(),exp=new Date(Date.now()+1800000);appendRow_(SS().getSheetByName('PasswordResets'),[hash_(t),u.UserID,exp,'',new Date()]);sendImmediateMail_(u.Email,'ตั้งรหัสผ่านใหม่ RASME',`เรียน ${u.FullName}\n\nเปิดลิงก์นี้ภายใน 30 นาที\n${webAppUrl_()}?reset=${encodeURIComponent(t)}`,'PasswordReset',u.UserID);}return{success:true,message:'หากพบข้อมูล ระบบจะส่งลิงก์ไปยังอีเมลที่ลงทะเบียน'};}
function resetPassword(t,p){return withMutationLock_(()=>resetPasswordLocked_(t,p));}
function resetPasswordLocked_(t,p){if(String(p||'').length<8)throw Error('รหัสผ่านต้องมีอย่างน้อย 8 ตัวอักษร');const sh=SS().getSheetByName('PasswordResets'),r=find_(sh,'TokenHash',hash_(t||''));if(!r||r.UsedAt||new Date(r.ExpiresAt)<new Date())throw Error('ลิงก์หมดอายุหรือถูกใช้แล้ว');const salt=token_();update_(SS().getSheetByName('Users'),'UserID',r.UserID,{Salt:salt,PasswordHash:passV2_(p,salt),UpdatedAt:new Date()});update_(sh,'TokenHash',r.TokenHash,{UsedAt:new Date()});return{success:true};}

function getProcedureDetail(token,pid){require_(token);const cache=CacheService.getScriptCache(),version=cache.get('procedure-detail-version')||'0',key='procedure-detail:v5:'+version+':'+String(pid),saved=cache.get(key);if(saved){try{return JSON.parse(saved);}catch(e){}}const ctx=prepareContext_({bookings:cachedSheetRows_('ActiveBookings',20),sessions:cachedSheetRows_('Sessions',60),procedures:cachedSheetRows_('Procedures',300),settings:cachedSettings_()});const p=proceduresFromRows_(ctx.procedures).find(x=>String(x.id)===String(pid));if(!p)throw Error('ไม่พบหัตถการ');if(p.status!=='Active')throw Error('หัตถการนี้ยังไม่เปิดให้จอง');const today=date_(new Date()),sessions=ctx.sessions.filter(s=>String(s.ProcedureID)===String(pid)&&['Open','Full','Confirmed'].includes(String(s.Status))).map(s=>sessionView_(s,ctx)).filter(s=>s.date>=today).sort((a,b)=>(a.date+a.startTime).localeCompare(b.date+b.startTime)),result=JSON.parse(JSON.stringify({procedure:p,sessions}));try{cache.put(key,JSON.stringify(result),20);}catch(e){}return result;}
function createBooking(token,sid){
 const authUser=require_(token),lock=LockService.getScriptLock();let d,u,isDuplicate=false;
 lock.waitLock(30000);
 try{
  u=find_(SS().getSheetByName('Users'),'UserID',authUser.UserID);
  if(!u||String(u.Status)!=='Active')throw Error('บัญชีนี้ไม่พร้อมใช้งาน');
  const banExpired=!!(u.BanUntil&&new Date(u.BanUntil)<=new Date());refreshBan_(u);if(banExpired){u.BanUntil='';u.NoShowCount=0;}
  if(banned_(u))throw Error(`ถูกระงับสิทธิ์ถึง ${dt_(u.BanUntil)}`);
  if(yes_(u.EvaluationPending))throw Error('คุณ Check-out แล้ว แต่ยังไม่ได้ทำแบบประเมิน กรุณาทำแบบประเมินรอบล่าสุดในเมนูการจองของฉันก่อนจองรอบใหม่');
  const active=rows_(SS().getSheetByName('ActiveBookings')),session=find_(SS().getSheetByName('Sessions'),'SessionID',sid),procedure=session?find_(SS().getSheetByName('Procedures'),'ProcedureID',session.ProcedureID):null,ctx=prepareContext_({bookings:active,sessions:session?[session]:[],procedures:procedure?[procedure]:[],users:[u],settings:cachedSettings_()}),same=active.find(b=>String(b.UserID)===String(u.UserID)&&String(b.SessionID)===String(sid));
  if(same){d=bookingView_(same,ctx);isDuplicate=true;}
  else{
   const existing=active.find(b=>String(b.UserID)===String(u.UserID));
   if(existing){
    if(String(existing.Status)==='CheckedIn')throw Error('คุณมีรอบที่กำลังใช้งานอยู่ กรุณากด Check-out ในเมนูการจองของฉัน และทำแบบประเมินก่อนจองรอบใหม่');
    if(String(existing.Status)==='CheckedOut')throw Error('คุณ Check-out แล้ว แต่ยังไม่ได้ทำแบบประเมิน กรุณาทำแบบประเมินในเมนูการจองของฉันก่อนจองรอบใหม่');
    throw Error('คุณมีรอบที่จองไว้แล้ว จึงยังไม่สามารถจองรอบหรือหัตถการอื่นได้ กรุณาตรวจสอบที่เมนูการจองของฉัน');
   }
   const s=session;
   if(!s||String(s.Status)!=='Open')throw Error('รอบนี้ไม่เปิดรับจอง');
   if(!procedure||String(procedure.Status).trim()!=='Active')throw Error('หัตถการนี้ยังไม่เปิดให้จอง');
   const v=sessionView_(s,ctx);
   if(!v.canBook)throw Error(v.closeReason||'ปิดรับจองแล้ว');
   if(v.booked>=v.maxCapacity)throw Error('รอบนี้เต็มแล้ว');
   const bid=id_('BK'),now=new Date(),booking={BookingID:bid,UserID:u.UserID,SessionID:sid,Status:'Reserved',BookedAt:now,CancelledAt:'',CheckInAt:'',CheckOutAt:'',EvaluationCompletedAt:'',UpdatedBy:u.UserID,Notes:''};
   appendBooking_(booking);ctx.bookings.push(booking);
   if(v.booked+1>=v.maxCapacity)update_(SS().getSheetByName('Sessions'),'SessionID',sid,{Status:'Full'});
   d=bookingView_(booking,ctx);
  }
 }finally{lock.releaseLock();}
 let notificationQueued=isDuplicate;
 if(!isDuplicate){try{notifyBooking_(u,d,false);notificationQueued=true;}catch(notificationError){notificationQueued=false;}}
 return{ok:true,success:true,bookingId:d.id,status:d.status,message:isDuplicate?'พบรายการจองเดิมแล้ว':'จองรอบเรียบร้อยแล้ว',alreadyProcessed:isDuplicate,booking:d,duplicate:isDuplicate,notificationQueued:notificationQueued};
}
function cancelMyBooking(token,bid){const u=require_(token),lock=LockService.getScriptLock();let d;lock.waitLock(15000);try{const master=SS().getSheetByName('Bookings'),b=find_(master,'BookingID',bid);if(!b||String(b.UserID)!==String(u.UserID)||!['Reserved','Confirmed'].includes(String(b.Status)))throw Error('ไม่สามารถยกเลิกรายการนี้ได้ กรุณาโหลดหน้าการจองใหม่');const s=find_(SS().getSheetByName('Sessions'),'SessionID',b.SessionID);if(!s)throw Error('ไม่พบรอบที่จอง กรุณาติดต่อเจ้าหน้าที่');const cut=cutoff_(s.SessionDate,+setting_('CANCELLATION_DAYS',3));if(new Date()>cut)throw Error(`ยกเลิกได้ถึง ${dt_(cut)} เท่านั้น`);updateBooking_(bid,{Status:'Cancelled',CancelledAt:new Date(),UpdatedBy:u.UserID},true);if(String(s.Status)==='Full')update_(SS().getSheetByName('Sessions'),'SessionID',s.SessionID,{Status:'Open'});invalidateBookingCaches_();d=bookingView_(find_(master,'BookingID',bid));}finally{lock.releaseLock();}notifyBooking_(u,d,true);return{success:true};}
function getMyDashboard(token){const auth=require_(token);reconcileUserNoShows_(auth.UserID);const u=find_(SS().getSheetByName('Users'),'UserID',auth.UserID)||auth;refreshBan_(u);const history=rowsMatchingColumn_(SS().getSheetByName('Bookings'),'UserID',value=>String(value)===String(u.UserID)),ctx={bookings:cachedSheetRows_('ActiveBookings',15),sessions:cachedSheetRows_('Sessions',60),procedures:cachedSheetRows_('Procedures',300),users:[u],settings:cachedSettings_()};return{user:publicUser_(u),bookings:history.map(b=>bookingView_(b,ctx)).reverse()};}
function getMyBookingCheckInStatus(token,bid){const u=require_(token),ss=SS(),active=find_(ss.getSheetByName('ActiveBookings'),'BookingID',bid),booking=active||find_(ss.getSheetByName('Bookings'),'BookingID',bid);if(!booking||String(booking.UserID)!==String(u.UserID))throw Error('ไม่พบรายการจองของคุณ');const status=String(booking.Status||''),terminal=!['Reserved','Confirmed'].includes(status);return{ok:true,bookingId:String(booking.BookingID),status:status,checkInAt:booking.CheckInAt?dt_(booking.CheckInAt):'',terminal:terminal};}
function reconcileUserNoShows_(userId){const ss=SS(),now=new Date(),grace=+setting_('NO_SHOW_GRACE_MINUTES',15),sessions=cachedSheetRows_('Sessions',60),active=cachedSheetRows_('ActiveBookings',15),isOverdue=b=>{const s=sessions.find(x=>String(x.SessionID)===String(b.SessionID));return s&&now>new Date(range_(s).start.getTime()+grace*60000);};if(!active.some(b=>String(b.UserID)===String(userId)&&['Reserved','Confirmed'].includes(String(b.Status))&&isOverdue(b)))return;const lock=LockService.getScriptLock();if(!lock.tryLock(3000))return;try{const latestSessions=cachedSheetRows_('Sessions',60);cachedSheetRows_('ActiveBookings',15).filter(b=>String(b.UserID)===String(userId)&&['Reserved','Confirmed'].includes(String(b.Status))).forEach(b=>{const s=latestSessions.find(x=>String(x.SessionID)===String(b.SessionID));if(s&&new Date()>new Date(range_(s).start.getTime()+grace*60000))noShow_(b);});}finally{lock.releaseLock();}}

function checkoutMyBooking(token,bid){const u=require_(token),lock=LockService.getScriptLock();lock.waitLock(15000);try{const active=SS().getSheetByName('ActiveBookings'),b=find_(active,'BookingID',bid);if(!b||String(b.UserID)!==String(u.UserID))throw Error('ไม่พบรายการจองของคุณ');if(String(b.Status)!=='CheckedIn')throw Error('รายการนี้ยังไม่ได้ Check-in หรือ Check-out ไปแล้ว');const now=new Date(),changes={Status:'CheckedOut',CheckOutAt:now,UpdatedBy:u.UserID,Notes:'ผู้ใช้ Check-out ผ่านหน้าการจอง'};update_(SS().getSheetByName('Bookings'),'BookingID',bid,changes);updateRow_(active,b._row,changes);update_(SS().getSheetByName('Users'),'UserID',u.UserID,{EvaluationPending:true,UpdatedAt:now});invalidateBookingCaches_();return{success:true,needsEvaluation:true,bookingId:bid,checkOutAt:dt_(now)};}finally{lock.releaseLock();}}
function submitEvaluation(token,bid,rating,feedback){return withMutationLock_(()=>submitEvaluationLocked_(token,bid,rating,feedback));}
