function validateEvaluationV4_(answers){
 if(!answers||typeof answers!=='object')throw Error('กรุณาตอบแบบประเมินให้ครบทุกข้อ');const out={};
 ['satisfactionStaff','satisfactionEquipment','satisfactionEnvironment','satisfactionOverall','satisfactionReturn','satisfactionRecommend','confidenceSelfPracticeBefore','confidenceSelfPracticeAfter'].forEach(k=>{const value=answers[k];if(typeof value!=='number'||!Number.isInteger(value)||value<1||value>5)throw Error('กรุณาให้คะแนนแบบประเมิน 1–5 ให้ครบทุกข้อ');out[k]=value;});
 [['mostImpressed','สิ่งที่ประทับใจมากที่สุด'],['improvementNeeded','สิ่งที่ควรปรับปรุงหรือพัฒนา'],['otherSuggestion','ข้อเสนอแนะอื่น ๆ']].forEach(item=>{const value=String(answers[item[0]]||'').trim();if(!value)throw Error('กรุณากรอก'+item[1]);if(value.length>2000)throw Error(item[1]+'ต้องไม่เกิน 2,000 ตัวอักษร');out[item[0]]=value;});return out;
}
function validateEvaluationV3_(answers){
 if(!answers||typeof answers!=='object')throw Error('กรุณาตอบแบบประเมินให้ครบ');const out={};
 const satisfaction=['satisfactionStaff','satisfactionEquipment','satisfactionEnvironment','satisfactionOverall'];
 const confidence=['confidenceCoreBefore','confidenceCoreAfter','confidenceSafetyBefore','confidenceSafetyAfter','confidenceComplicationsBefore','confidenceComplicationsAfter'];
 [...satisfaction,...confidence].forEach(k=>{const value=answers[k],max=confidence.includes(k)?10:5;if(typeof value!=='number'||!Number.isInteger(value)||value<1||value>max)throw Error(max===10?'กรุณาให้คะแนนความมั่นใจก่อนและหลังฝึก 1–10 ให้ครบทั้ง 3 ข้อ':'กรุณาให้คะแนนความพึงพอใจ 1–5 ให้ครบทั้ง 4 ข้อ');out[k]=value;});
 out.feedback=String(answers.feedback||'').trim();if(out.feedback.length>2000)throw Error('ข้อเสนอแนะต้องไม่เกิน 2,000 ตัวอักษร');return out;
}
function validateEvaluationV2_(answers){
 if(!answers||typeof answers!=='object')throw Error('กรุณาตอบแบบประเมินให้ครบทุกข้อ');
 const out={};
 ['satisfactionBooking','satisfactionEquipment','satisfactionEnvironment','satisfactionOverall','confidenceBefore','confidenceAfter'].forEach(k=>{
  const value=answers[k],confidence=k.startsWith('confidence'),min=confidence?0:1,max=confidence?10:5;
  if(typeof value!=='number'||!Number.isInteger(value)||value<min||value>max)throw Error(confidence?'กรุณาให้คะแนนความมั่นใจ 0–10 ให้ครบทั้งสองข้อ':'กรุณาให้คะแนนความพึงพอใจ 1–5 ให้ครบทุกข้อ');
  out[k]=value;
 });
 out.feedback=String(answers.feedback||'').trim();if(out.feedback.length>2000)throw Error('ข้อเสนอแนะต้องไม่เกิน 2,000 ตัวอักษร');return out;
}
function ensureEvaluationHeaders_(sh){
 const cache=typeof CacheService!=='undefined'?CacheService.getScriptCache():null,cacheKey='evaluation-headers:v1',saved=cache?cache.get(cacheKey):'';if(saved){try{const parsed=JSON.parse(saved);if(Array.isArray(parsed)&&parsed.length>=6)return parsed;}catch(e){}}
 const headers=sh.getRange(1,1,1,Math.max(sh.getLastColumn(),6)).getValues()[0].map(String);
 const base=SCHEMAS.Evaluations.slice(0,6);if(base.some((h,i)=>headers[i]!==h))throw Error('โครงสร้างชีต Evaluations ไม่ตรง กรุณาติดต่อผู้ดูแลระบบ');
 while(headers.length&&headers[headers.length-1]==='')headers.pop();
 const missing=SCHEMAS.Evaluations.filter(k=>!headers.includes(k));
 if(missing.length){if(headers.length+missing.length>sh.getMaxColumns())sh.insertColumnsAfter(sh.getMaxColumns(),headers.length+missing.length-sh.getMaxColumns());sh.getRange(1,headers.length+1,1,missing.length).setValues([missing]);headers.push(...missing);}
 try{if(cache)cache.put(cacheKey,JSON.stringify(headers),600);}catch(e){}return headers;
}
function submitEvaluationLocked_(token,bid,rating,feedback){const u=require_(token),b=find_(SS().getSheetByName('ActiveBookings'),'BookingID',bid),score=+rating;if(!b||b.UserID!==u.UserID||b.Status!=='CheckedOut')throw Error('ไม่พบรายการที่รอประเมิน');if(!Number.isInteger(score)||score<1||score>5)throw Error('กรุณาให้คะแนน 1–5');SS().getSheetByName('Evaluations').appendRow([id_('EV'),bid,u.UserID,score,clean_(feedback),new Date()]);updateBooking_(bid,{Status:'Completed',EvaluationCompletedAt:new Date(),UpdatedBy:u.UserID},true);update_(SS().getSheetByName('Users'),'UserID',u.UserID,{EvaluationPending:false,UpdatedAt:new Date()});return{success:true};}

function getAdminDashboard(token){const u=require_(token);if(u.Role!=='Admin')throw Error('ไม่มีสิทธิ์');const cache=CacheService.getScriptCache(),key='dashboard:v1',saved=cache.get(key);if(saved){try{return JSON.parse(saved);}catch(e){}}const ctx=dataContext_(),views=ctx.sessions.map(s=>sessionView_(s,ctx)),seen={},rooms=[];views.forEach(s=>{const key=roomKey_(s.room,s.floor);if(key&&!seen[key]){seen[key]=true;rooms.push({key:key,room:s.room,floor:s.floor});}});const result={sessions:views,bookings:ctx.bookingHistory.map(b=>bookingView_(b,ctx)),procedures:proceduresFromRows_(ctx.procedures),rooms:rooms,totalBookings:ctx.totalBookings};try{cache.put(key,JSON.stringify(result),15);}catch(e){}return result;}
function adminQuickCheckIn(token,bid){return withMutationLock_(()=>adminQuickCheckInLocked_(token,bid));}
function adminQuickCheckInLocked_(token,bid){const admin=require_(token);if(String(admin.Role)!=='Admin')throw Error('ไม่มีสิทธิ์');const ss=SS(),booking=find_(ss.getSheetByName('ActiveBookings'),'BookingID',bid);if(!booking)throw Error('ไม่พบรายการจองที่รอ Check-in');if(!['Reserved','Confirmed'].includes(String(booking.Status)))throw Error('รายการนี้ไม่อยู่ในสถานะที่ Check-in ได้');const session=find_(ss.getSheetByName('Sessions'),'SessionID',booking.SessionID);if(!session)throw Error('ไม่พบข้อมูลรอบที่จอง');const now=new Date(),range=range_(session),grace=+setting_('NO_SHOW_GRACE_MINUTES',15),opens=new Date(range.start.getTime()-1800000),closes=new Date(range.start.getTime()+grace*60000);if(now<opens||now>closes)throw Error(`รอบนี้ Check-in ได้เวลา ${Utilities.formatDate(opens,TZ,'HH:mm')}–${Utilities.formatDate(closes,TZ,'HH:mm')} น.`);updateBooking_(bid,{Status:'CheckedIn',CheckInAt:now,UpdatedBy:admin.UserID,Notes:'เจ้าหน้าที่ Check-in จากหน้าปฏิบัติงาน'},false);const updated=Object.assign({},booking,{Status:'CheckedIn',CheckInAt:now});return{success:true,booking:mutationBookingView_(updated,session),confirmedAt:dt_(now)};}
function adminCompleteCheckout(token,bid){return withMutationLock_(()=>adminCompleteCheckoutLocked_(token,bid));}
function adminCompleteCheckoutLocked_(token,bid){const a=require_(token);if(a.Role!=='Admin')throw Error('ไม่มีสิทธิ์');const b=find_(SS().getSheetByName('ActiveBookings'),'BookingID',bid);if(!b||b.Status!=='CheckedIn')throw Error('รายการไม่ได้ Check-in');const now=new Date(),updated=Object.assign({},b,{Status:'CheckedOut',CheckOutAt:now,UpdatedBy:a.UserID,Notes:'เจ้าหน้าที่ Check-out ให้'});updateBooking_(bid,{Status:'CheckedOut',CheckOutAt:now,UpdatedBy:a.UserID,Notes:'เจ้าหน้าที่ Check-out ให้'},false);update_(SS().getSheetByName('Users'),'UserID',b.UserID,{EvaluationPending:true,UpdatedAt:now});return{success:true,booking:mutationBookingView_(updated)};}
function adminUpdateBookingStatus(token,bid,status,note){const result=withMutationLock_(()=>adminUpdateBookingStatusLocked_(token,bid,status,note));if(!result||typeof result!=='object')return result;const notification=result._notification;delete result._notification;if(notification){try{notifyCancellation_(notification.user,notification.details,notification.reason,notification.event);result.notificationQueued=true;}catch(e){result.notificationQueued=false;}}return result;}
function adminUpdateBookingStatusLocked_(token,bid,status,note){
 const admin=require_(token);if(String(admin.Role)!=='Admin')throw Error('ไม่มีสิทธิ์');
 const allowed=['Reserved','Confirmed','CheckedIn','CheckedOut','Completed','Cancelled','NoShow','SessionCancelled'];
 status=String(status||'').trim();if(!allowed.includes(status))throw Error('สถานะที่เลือกไม่ถูกต้อง');
 note=clean_(note);if(note.length>300)throw Error('หมายเหตุต้องไม่เกิน 300 ตัวอักษร');const auditNote=note||'ไม่ได้ระบุเหตุผล';
 const ss=SS(),master=ss.getSheetByName('Bookings'),booking=find_(master,'BookingID',bid);if(!booking)throw Error('ไม่พบรายการจอง');
 const previous=String(booking.Status),now=new Date();if(previous===status)return{success:true,unchanged:true};
 const changes={Status:status,UpdatedBy:admin.UserID,Notes:`ผู้ดูแลปรับสถานะ ${previous} → ${status}: ${auditNote}`};
 if(status==='CheckedIn'&&!booking.CheckInAt)changes.CheckInAt=now;
 if(status==='CheckedOut'&&!booking.CheckOutAt)changes.CheckOutAt=now;
 if(status==='Cancelled'&&!booking.CancelledAt)changes.CancelledAt=now;
 if(status==='Completed'&&!booking.EvaluationCompletedAt)changes.EvaluationCompletedAt=now;
 update_(master,'BookingID',bid,changes);
 const terminal=['Completed','Cancelled','NoShow','SessionCancelled'].includes(status),activeSheet=ss.getSheetByName('ActiveBookings'),active=find_(activeSheet,'BookingID',bid);
 if(terminal){if(active)deleteWhere_(activeSheet,r=>String(r.BookingID)===String(bid));}
 else if(active)update_(activeSheet,'BookingID',bid,changes);
 else{const restored=Object.assign({},booking,changes);activeSheet.appendRow(SCHEMAS.ActiveBookings.map(k=>restored[k]===undefined?'':restored[k]));}
 const user=find_(ss.getSheetByName('Users'),'UserID',booking.UserID);if(user){
  const userChanges={UpdatedAt:now};
  if(previous==='NoShow'&&status!=='NoShow'){userChanges.NoShowCount=Math.max(0,(+user.NoShowCount||0)-1);if(userChanges.NoShowCount<+setting_('NO_SHOW_LIMIT',3))userChanges.BanUntil='';}
  if(previous!=='NoShow'&&status==='NoShow'){userChanges.NoShowCount=(+user.NoShowCount||0)+1;if(userChanges.NoShowCount>=+setting_('NO_SHOW_LIMIT',3)){const ban=new Date(now);ban.setDate(ban.getDate()+(+setting_('SUSPENSION_DAYS',3)));userChanges.BanUntil=ban;}}
  userChanges.EvaluationPending=status==='CheckedOut';update_(ss.getSheetByName('Users'),'UserID',booking.UserID,userChanges);
 }
 const updated=Object.assign({},booking,changes),view=mutationBookingView_(updated,null,user),result={success:true,previousStatus:previous,status:status,booking:view};
 if(user&&['Cancelled','SessionCancelled'].includes(status))result._notification={user:user,details:view,reason:note||(status==='SessionCancelled'?'รอบฝึกถูกยกเลิกโดยผู้ดูแลระบบ':'รายการจองถูกยกเลิกโดยผู้ดูแลระบบ'),event:status==='SessionCancelled'?'AdminSessionCancelled':'AdminBookingCancelled'};
 invalidateBookingCaches_();return result;
}

function processAutomations(){ensureProductionUpgrade_();processNotificationQueue_();const result=withMutationLock_(()=>processAutomationsLocked_());processNotificationQueue_();return result;}
function processAutomationsLocked_(){
 try{
  const now=new Date(),grace=+setting_('NO_SHOW_GRACE_MINUTES',15),active=rows_(SS().getSheetByName('ActiveBookings')),sessions=rows_(SS().getSheetByName('Sessions')),ctx=prepareContext_({bookings:active,sessions:sessions,procedures:cachedSheetRows_('Procedures',300),users:rows_(SS().getSheetByName('Users')),settings:cachedSettings_()}),cancellationResults=[];
  active.filter(b=>['Reserved','Confirmed'].includes(String(b.Status))).forEach(b=>{const s=ctx._sessionsById[String(b.SessionID)];if(!s||String(s.Status)==='Cancelled')return;const r=range_(s);if(now>new Date(r.start.getTime()+grace*60000))noShow_(b);else{const prior=new Date(r.start);prior.setDate(prior.getDate()-1);if(date_(prior)===date_(now))reminder_(b);}});
  sessions.forEach(s=>{const v=sessionView_(s,ctx),status=String(s.Status),closed=now>cutoff_(s.SessionDate,+s.BookingCloseDays||+contextSetting_(ctx,'BOOKING_CLOSE_DAYS',7)),pending=(ctx._bookingsBySession[String(s.SessionID)]||[]).some(b=>['Reserved','Confirmed','SessionCancelled'].includes(String(b.Status)));if(['Open','Full'].includes(status)&&closed){if(v.booked<v.minCapacity){update_(SS().getSheetByName('Sessions'),'SessionID',s.SessionID,{Status:'Cancelled'});s.Status='Cancelled';cancellationResults.push(cancelSession_(s.SessionID,ctx));}else{update_(SS().getSheetByName('Sessions'),'SessionID',s.SessionID,{Status:'Confirmed'});(ctx._bookingsBySession[String(s.SessionID)]||[]).filter(b=>b.Status==='Reserved').forEach(b=>updateBooking_(b.BookingID,{Status:'Confirmed',UpdatedBy:'SYSTEM'},false));telegram_(`✅ ยืนยันรอบ ${v.procedureName} ${v.dateDisplay} ${v.timeDisplay} ${v.booked}/${v.maxCapacity} คน`,'SessionConfirmed',s.SessionID);}}else if(status==='Cancelled'&&pending)cancellationResults.push(cancelSession_(s.SessionID,ctx));});
  dailyMaintenance_();return{success:true,cancellations:cancellationResults};
 }catch(e){systemLog_('Error','Automation','',e.stack||e.message);throw e;}
}
function installAutomationTriggers(){ScriptApp.getProjectTriggers().filter(t=>['processAutomations','dailyMaintenance'].includes(t.getHandlerFunction())).forEach(t=>ScriptApp.deleteTrigger(t));ScriptApp.newTrigger('processAutomations').timeBased().everyMinutes(1).create();ScriptApp.newTrigger('dailyMaintenance').timeBased().atHour(2).everyDays(1).create();return{success:true};}
function noShow_(b){updateBooking_(b.BookingID,{Status:'NoShow',UpdatedBy:'SYSTEM'},true);const u=find_(SS().getSheetByName('Users'),'UserID',b.UserID),count=+u.NoShowCount+1,limit=+setting_('NO_SHOW_LIMIT',3);let ban='';if(count>=limit){ban=new Date();ban.setDate(ban.getDate()+(+setting_('SUSPENSION_DAYS',3)));}update_(SS().getSheetByName('Users'),'UserID',u.UserID,{NoShowCount:count,BanUntil:ban,UpdatedAt:new Date()});sendMail_(u.Email,ban?'แจ้งระงับสิทธิ์ RASME':'แจ้ง No-show',ban?`ถูกระงับสิทธิ์ถึง ${dt_(ban)}`:`No-show ครั้งที่ ${count}`,'NoShow',b.BookingID);}
function refreshBan_(u){if(u.BanUntil&&new Date(u.BanUntil)<=new Date())update_(SS().getSheetByName('Users'),'UserID',u.UserID,{BanUntil:'',NoShowCount:0,UpdatedAt:new Date()});}

function dataContext_(){const ss=SS(),master=ss.getSheetByName('Bookings');return prepareContext_({bookings:cachedSheetRows_('ActiveBookings',15),bookingHistory:tailRows_(master,300),totalBookings:Math.max(0,master.getLastRow()-1),sessions:cachedSheetRows_('Sessions',60),procedures:cachedSheetRows_('Procedures',300),users:cachedSheetRows_('Users',30),settings:cachedSettings_()});}
function bookingContext_(booking){const ss=SS(),session=find_(ss.getSheetByName('Sessions'),'SessionID',booking.SessionID),procedure=session?find_(ss.getSheetByName('Procedures'),'ProcedureID',session.ProcedureID):null,user=find_(ss.getSheetByName('Users'),'UserID',booking.UserID);return prepareContext_({bookings:rows_(ss.getSheetByName('ActiveBookings')),sessions:session?[session]:[],procedures:procedure?[procedure]:[],users:user?[user]:[],settings:cachedSettings_()});}
function mutationBookingView_(booking,session,user){const ss=SS();session=session||find_(ss.getSheetByName('Sessions'),'SessionID',booking.SessionID);const procedure=session?find_(ss.getSheetByName('Procedures'),'ProcedureID',session.ProcedureID):null;user=user||find_(ss.getSheetByName('Users'),'UserID',booking.UserID);return bookingView_(booking,prepareContext_({bookings:[booking],sessions:session?[session]:[],procedures:procedure?[procedure]:[],users:user?[user]:[],settings:cachedSettings_()}));}
function settingsMap_(){const out={};rows_(SS().getSheetByName('Settings')).forEach(r=>out[String(r.Key)]=r.Value);return out;}
function contextSetting_(ctx,key,fallback){return ctx&&ctx.settings&&ctx.settings[key]!==''&&ctx.settings[key]!==undefined?ctx.settings[key]:setting_(key,fallback);}
function prepareContext_(ctx){if(!ctx)return ctx;const bookings=ctx.bookings||[],sessions=ctx.sessions||[],procedures=ctx.procedures||[],users=ctx.users||[];if(!ctx._sessionsById){ctx._sessionsById={};sessions.forEach(x=>ctx._sessionsById[String(x.SessionID)]=x);}if(!ctx._proceduresById){ctx._proceduresById={};procedures.forEach(x=>ctx._proceduresById[String(x.ProcedureID)]=x);}if(!ctx._usersById){ctx._usersById={};users.forEach(x=>ctx._usersById[String(x.UserID)]=x);}if(ctx._bookingIndexSize!==bookings.length){ctx._bookingsBySession={};bookings.forEach(x=>{const key=String(x.SessionID);(ctx._bookingsBySession[key]||(ctx._bookingsBySession[key]=[])).push(x);});ctx._bookingIndexSize=bookings.length;}return ctx;}
