function rows_(s){const v=s.getDataRange().getValues();if(v.length<2)return[];const h=v[0].map(String);return v.slice(1).map((r,i)=>{if(!r.some(x=>x!==''))return null;const o={_row:i+2};h.forEach((x,j)=>o[x]=r[j]);return o;}).filter(Boolean);}
function sheetHeaders_(s){const name=typeof s.getName==='function'?s.getName():'',known=SCHEMAS[name];if(known)return known.slice();const width=Math.max(1,typeof s.getLastColumn==='function'?s.getLastColumn():1);return s.getRange(1,1,1,width).getValues()[0].map(String);}
function tailRows_(s,limit){const headers=sheetHeaders_(s),last=s.getLastRow(),count=Math.min(Math.max(0,last-1),Math.max(0,+limit||0));if(!count)return[];const start=last-count+1,values=s.getRange(start,1,count,headers.length).getValues();return values.map((row,index)=>{const out={_row:start+index};headers.forEach((key,column)=>out[key]=row[column]);return out;}).filter(row=>headers.some(key=>row[key]!==''));}
function rowsMatchingColumn_(s,key,predicate){const headers=sheetHeaders_(s),column=headers.indexOf(key),last=s.getLastRow();if(column<0||last<2)return[];const values=s.getRange(2,column+1,last-1,1).getValues(),rows=[];values.forEach((value,index)=>{if(predicate(value[0]))rows.push(index+2);});if(!rows.length)return[];const groups=[];rows.forEach(row=>{const lastGroup=groups[groups.length-1];if(lastGroup&&lastGroup.start+lastGroup.count===row)lastGroup.count++;else groups.push({start:row,count:1});});const out=[];groups.forEach(group=>s.getRange(group.start,1,group.count,headers.length).getValues().forEach((value,index)=>{const item={_row:group.start+index};headers.forEach((header,col)=>item[header]=value[col]);out.push(item);}));return out;}
function columnHas_(s,key,predicate){const headers=sheetHeaders_(s),column=headers.indexOf(key),last=s.getLastRow();if(column<0||last<2)return false;return s.getRange(2,column+1,last-1,1).getValues().some(row=>predicate(row[0]));}
function findRowNumber_(s,key,value,headers){headers=headers||sheetHeaders_(s);const column=headers.indexOf(key),last=typeof s.getLastRow==='function'?s.getLastRow():0;if(column<0||last<2)return-1;const values=s.getRange(2,column+1,last-1,1).getValues();for(let i=0;i<values.length;i++)if(String(values[i][0])===String(value))return i+2;return-1;}
