function appendBooking_(b){['Bookings','ActiveBookings'].forEach(n=>{const sh=SS().getSheetByName(n);appendRow_(sh,SCHEMAS[n].map(k=>b[k]===undefined?'':b[k]));});invalidateBookingCaches_();}function updateBooking_(id,changes,terminal){update_(SS().getSheetByName('Bookings'),'BookingID',id,changes);if(terminal)deleteWhere_(SS().getSheetByName('ActiveBookings'),r=>String(r.BookingID)===String(id));else update_(SS().getSheetByName('ActiveBookings'),'BookingID',id,changes);invalidateBookingCaches_();}
