 active.forEach(candidate=>{try{const booking=find_(master,'BookingID',candidate.BookingID);if(!booking){result.failed++;return;}const status=String(booking.Status);if(['Reserved','Confirmed'].includes(status)){if(!updateRow_(master,booking._row,{Status:'SessionCancelled',UpdatedBy:'SYSTEM',Notes:reason}))throw Error('ไม่สามารถปรับสถานะรายการจองได้');}else if(status==='SessionCancelled')result.skipped++;else{deleteRows.push(candidate._row);result.skipped++;return;}const cancelled=Object.assign({},booking,{Status:'SessionCancelled',UpdatedBy:'SYSTEM',Notes:reason}),details=bookingView_(cancelled,ctx),user=ctx&&ctx._usersById&&ctx._usersById[String(candidate.UserID)]||find_(ss.getSheetByName('Users'),'UserID',candidate.UserID);if(notifyCancellation_(user,details,reason,'SessionCancelled'))result.queued++;deleteRows.push(candidate._row);result.processed++;}catch(e){result.failed++;}});
